import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_each_transcript_equally():
    groups = {"a": [{"flagged": False}] * 3, "b": [{"flagged": True}], "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"a": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (2, 6), (10, 7)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 4], days) == expected


def test_parse_skips_comments_and_blank_lines_and_strips_fields():
    lines = ["", " \t", "  # comment", " a , 1 , 1 ", "b,2, 0", " c, 3, "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["a,1", "a,1,0,extra", "a,not-an-int,1"])
def test_parse_reports_original_line_number(bad):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["a,1,0", "", " # comment", bad])


def test_dedupe_keeps_last_duplicate_id_then_sorts():
    events = parse_transcript_log(["z,8,1", "b,4,1", "a,4,0", "z,2,0"])
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]


def test_daily_flag_counts_includes_gaps_and_ignores_outside_days():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,4,1", "f,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["a,1,1", "b,4,1"]),
              "b": parse_transcript_log(["c,4,0"]), "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_filters_before_ranking_and_breaks_ties_by_name():
    groups = {"c": [{"flagged": True}], "b": [{"flagged": False}],
              "a": [{"flagged": True}], "d": []}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "c", "b"]


def test_group_rates_are_sorted_and_include_empty_groups():
    groups = {"c": [{"flagged": True}], "b": [], "a": [{"flagged": None}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", None), ("c", 1.0)]


@pytest.mark.parametrize("counts,expected", [([], 0), ([0, -1], 0), ([1, 1, -1, 2, 0, 3], 2)])
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
